public class Main {
    public static void main(String[] args) {
        LockService lockService = new LockService();
        ProtectedResource resource = new ProtectedResource();

        // Client A acquires the lock at time 0, with a 1000ms time-to-live.
        LockGrant grantA = lockService.acquire("resource-1", "client-A", 0, 1000);
        System.out.println("Client A acquires lock: granted=" + grantA.granted + " token=" + grantA.token);

        // Client A "pauses" (a long GC pause or network partition) and never renews or releases.
        // Time passes well beyond the lock's 1000ms TTL.

        // Client B acquires the lock at time 1500, since A's lock has already expired.
        LockGrant grantB = lockService.acquire("resource-1", "client-B", 1500, 1000);
        System.out.println("Client B acquires lock after A's expired: granted=" + grantB.granted + " token=" + grantB.token);

        // Client B writes using its genuinely current, higher token.
        boolean bWriteAccepted = resource.applyWrite(grantB.token, "B's update");
        System.out.println("Client B's write accepted: " + bWriteAccepted);

        // Client A finally wakes up, still believing it holds token 1, and tries to write.
        boolean aWriteAccepted = resource.applyWrite(grantA.token, "A's stale update");
        System.out.println("Client A's stale write accepted (should be false): " + aWriteAccepted);

        System.out.println("Resource's final data (should only reflect B's write): " + resource.currentData());
    }
}

// The result of a lock acquisition attempt: whether it succeeded, and, if
// so, the strictly increasing fencing token issued for this grant.
class LockGrant {
    boolean granted;
    long token;

    LockGrant(boolean granted, long token) {
        this.granted = granted;
        this.token = token;
    }
}

// One resource's current lock state: who holds it, its fencing token, and
// when it expires.
class LockState {
    String ownerClientId;
    long token;
    long expiresAt;

    LockState(String ownerClientId, long token, long expiresAt) {
        this.ownerClientId = ownerClientId;
        this.token = token;
        this.expiresAt = expiresAt;
    }
}

// Grants exclusive locks with strictly increasing fencing tokens; a lock
// past its expiry is treated as free and can be granted to a new client
// with a genuinely higher token than any issued before.
class LockService {
    private final java.util.Map<String, LockState> locks = new java.util.HashMap<>();
    private long nextToken = 1;

    LockGrant acquire(String resourceId, String clientId, long now, long ttlMillis) {
        LockState existing = locks.get(resourceId);
        if (existing != null && existing.expiresAt > now) {
            return new LockGrant(false, -1); // still held by someone else, not yet expired
        }
        long token = nextToken++; // always strictly greater than any token issued before
        locks.put(resourceId, new LockState(clientId, token, now + ttlMillis));
        return new LockGrant(true, token);
    }
}

// A resource protected by fencing tokens: it independently rejects any
// write whose token is not higher than the highest one it has already
// accepted, regardless of what the lock service or the writing client believes.
class ProtectedResource {
    private long highestTokenSeen = 0;
    private String data = "";

    boolean applyWrite(long token, String newData) {
        if (token <= highestTokenSeen) {
            return false; // stale token: this client no longer safely holds the lock
        }
        highestTokenSeen = token;
        data = newData;
        return true;
    }

    String currentData() {
        return data;
    }
}

