#include <iostream>
#include <map>
#include <string>
using namespace std;

// The result of a lock acquisition attempt: whether it succeeded, and, if
// so, the strictly increasing fencing token issued for this grant.
struct LockGrant {
    bool granted;
    long token;
};

// One resource's current lock state: who holds it, its fencing token, and
// when it expires.
struct LockState {
    string ownerClientId;
    long token;
    long expiresAt;
};

// Grants exclusive locks with strictly increasing fencing tokens; a lock
// past its expiry is treated as free and can be granted to a new client
// with a genuinely higher token than any issued before.
class LockService {
public:
    LockGrant acquire(const string& resourceId, const string& clientId, long now, long ttlMillis) {
        auto it = locks.find(resourceId);
        if (it != locks.end() && it->second.expiresAt > now) {
            return {false, -1}; // still held by someone else, not yet expired
        }
        long token = nextToken++; // always strictly greater than any token issued before
        locks[resourceId] = {clientId, token, now + ttlMillis};
        return {true, token};
    }

private:
    map<string, LockState> locks;
    long nextToken = 1;
};

// A resource protected by fencing tokens: it independently rejects any
// write whose token is not higher than the highest one it has already
// accepted, regardless of what the lock service or the writing client believes.
class ProtectedResource {
public:
    bool applyWrite(long token, const string& newData) {
        if (token <= highestTokenSeen) {
            return false; // stale token: this client no longer safely holds the lock
        }
        highestTokenSeen = token;
        data = newData;
        return true;
    }

    string currentData() {
        return data;
    }

private:
    long highestTokenSeen = 0;
    string data = "";
};

int main() {
    LockService lockService;
    ProtectedResource resource;

    // Client A acquires the lock at time 0, with a 1000ms time-to-live.
    LockGrant grantA = lockService.acquire("resource-1", "client-A", 0, 1000);
    cout << "Client A acquires lock: granted=" << (grantA.granted ? "true" : "false") << " token=" << grantA.token << endl;

    // Client A "pauses" (a long GC pause or network partition) and never renews or releases.
    // Time passes well beyond the lock's 1000ms TTL.

    // Client B acquires the lock at time 1500, since A's lock has already expired.
    LockGrant grantB = lockService.acquire("resource-1", "client-B", 1500, 1000);
    cout << "Client B acquires lock after A's expired: granted=" << (grantB.granted ? "true" : "false") << " token=" << grantB.token << endl;

    // Client B writes using its genuinely current, higher token.
    bool bWriteAccepted = resource.applyWrite(grantB.token, "B's update");
    cout << "Client B's write accepted: " << (bWriteAccepted ? "true" : "false") << endl;

    // Client A finally wakes up, still believing it holds token 1, and tries to write.
    bool aWriteAccepted = resource.applyWrite(grantA.token, "A's stale update");
    cout << "Client A's stale write accepted (should be false): " << (aWriteAccepted ? "true" : "false") << endl;

    cout << "Resource's final data (should only reflect B's write): " << resource.currentData() << endl;

    return 0;
}

